mapper.select:
select * from (SELECT hpd.*, (select hbm.bp_name from hls_bp_master hbm where hpd.bp_id = hbm.bp_id) bp_name, (select fe.name from fnd_employee fe where fe.employee_id = hpd.employee_id) employee_name, (select distinct su.user_id from sys_user su, sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe where su.USER_ID = sua.user_id and sua.employee_assign_id = fea.employee_assign_id and fe.employee_id = fea.employee_id and sua.role_id = (select sb.role_id from sys_role_b sb where sb.role_code = 'B0030') and fe.employee_id = hpd.employee_id) as user_id, (SELECT fea.unit_id FROM fnd_employee fe, fnd_employee_assigns fea, fnd_org_position fop WHERE fe.employee_id = fea.employee_id AND fea.position_id = fop.position_id AND fea.enabled_flag = 'Y' AND fe.enabled_flag = 'Y' AND fop.position_type = 'SALES' AND fe.employee_id = hpd.employee_id) unit_id, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'PRODUCT.LEASE_ITEM_TYPE' and scb.code_id = scvb.code_id and scvb.value = hpd.lease_item_type) as lease_item_type_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'MARGIN_DEDUCTION_METHOD' and scb.code_id = scvb.code_id and scvb.value = hpd.margin_deduction_method) as margin_deduction_method_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'HLS500_PAY_TYPE' and scb.code_id = scvb.code_id and scvb.value = to_char(hpd.pay_type)) as pay_type_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'HLS500_ANNUAL_PAY_TIMES' and scb.code_id = scvb.code_id and scvb.value = to_char(hpd.annual_pay_times)) as annual_pay_times_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'EXEMPT_PENALTY_INT' and scb.code_id = scvb.code_id and scvb.value = hpd.exempt_penalty_int) as exempt_penalty_int_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'PAYMENT_BP_TYPE' and scb.code_id = scvb.code_id and scvb.value = hpd.payment_bp_type) as payment_bp_type_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'REPAY_BP_TYPE' and scb.code_id = scvb.code_id and scvb.value = hpd.repay_bp_type) as repay_bp_type_n, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'SIMPLE_COMPOUND_TYPE' and scb.code_id = scvb.code_id and scvb.value = hpd.simple_compound_type) as simple_compound_type_n, (SELECT hpl.description FROM hls_price_list hpl WHERE hpl.price_list = hpd.price_list) price_dist_display, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. code = 'FND.PRODUCT_STATUS' AND v.code_value = hpd.product_status) product_status_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'RESIDUAL_PRICE_TYPE' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = to_char(hpd.RESIDUAL_PRICE_TYPE)) RESIDUAL_PRICE_TYPE_N, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'SYS.YES_NO' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.step_quotation_flag) step_quotation_flag_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'RESIDUAL_VALUE_RECEIVED' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.residual_value_received) residual_value_received_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'REPAY_MODE' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.repay_mode) repay_mode_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'SYS.YES_NO' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.int_rate_calc_flag) int_rate_calc_flag_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'CHARGE_DISCOUNT_RULE' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.lease_charge_discount_rule) lease_charge_discount_rule_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'DISCOUNT_TIMES' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = hpd.rental_discount_times) rental_discount_times_n FROM hls_product_definition hpd) v v.document_type = 'PRODUCT_DEFINITION' and v.business_type = 'PRODUCT_DEFINITION'
AND v.definition_code LIKE CONCAT('%',CONCAT(#{definitionCode,jdbcType=VARCHAR},'%'))
AND v.definition_name LIKE CONCAT('%',CONCAT(#{definitionName,jdbcType=VARCHAR},'%'))
AND v.product_status = #{productStatus}
AND v.enabled_flag = #{enabledFlag}
AND v.definition_id = #{definitionId}
AND v.bp_name = #{bpName}
and v.bp_id=#{bpId}
ORDER BY v.definition_code DESC
